bool fits(vector<int>& w, int days, int cap) {
    int d = 1, cur = 0;
    for (int x : w) {
        if (cur + x > cap) { d++; cur = 0; }
        cur += x;
    }
    return d <= days;
}

int ship(vector<int>& w, int days) {
    int lo = *max_element(w.begin(), w.end());
    int hi = accumulate(w.begin(), w.end(), 0);
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (fits(w, days, mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

